const DateTypeSchema = z.iso.datetime({ offset: true }).openapi('DateType')

const CredentialsSchema = z
  .object({
    AccessKeyId: AccessKeyIdTypeSchema.and(
      z
        .any()
        .openapi({
          description: 'The access key ID that identifies the temporary security credentials.',
        }),
    ),
    SecretAccessKey: AccessKeySecretTypeSchema.and(
      z.any().openapi({ description: 'The secret access key that can be used to sign requests.' }),
    ),
    SessionToken: TokenTypeSchema.and(
      z
        .any()
        .openapi({
          description:
            'The token that users must pass to the service API to use the temporary credentials.',
        }),
    ),
    Expiration: DateTypeSchema.and(
      z.any().openapi({ description: 'The date on which the current credentials expire.' }),
    ),
  })
  .openapi({
    required: ['AccessKeyId', 'SecretAccessKey', 'SessionToken', 'Expiration'],
    description: 'Amazon Web Services credentials for API authentication.',
  })
  .openapi('Credentials')

